FUNCTION_BLOCK FB_PortTrolley_BrakingLaserAntiCollision
(*
====================================================================================================
 PROJECT:        LUMINA HIGH-INTEGRITY CYBER-PHYSICAL MARITIME AUTOMATION SUITE
 ARCHITECTURE:   IEC 61131-3 3RD EDITION COMPLIANT INDUSTRIAL ROBOTICS & ENERGY SUBSYSTEM
 DOMAIN:         AUTOMATED SHIP-TO-SHORE (STS) CONTAINER CRANE RAIL TROLLEY
 SUBSYSTEM:      DYNAMIC BRAKING CHOPPER ENERGY ABSORPTION & 2oo3 TMR LASER ANTI-COLLISION MPC
 HARDWARE TIER:  SIL-3 ARCHITECTURE (DUAL 1oo2D / TMR CPU) WITH HARD REAL-TIME 5ms CYCLE TIME
 AUTHOR:         PRINCIPAL AUTOMATION FELLOW & CYBER-PHYSICAL SYSTEMS CHAIR (V7 MAX PERSONA)
 REVISION:       7.4.2-HEAVY-DUTY
====================================================================================================
*)
VAR_INPUT
    (* --- Master Permissives & Safety Chain Feeds --- *)
    bEnable                 : BOOL;     (* Main Subsystem Motion & Power Electronics Permissive [1=Run, 0=Inhibit] *)
    bEStopOk                : BOOL;     (* Dual-Channel Hardwired Emergency Safety Relay Loop [1=Healthy, 0=Tripped] *)
    bBrakeContactorsClosed  : BOOL;     (* Spring-Applied Emergency Track Disc Brake Contactor Auxiliary Feedback [1=Closed, 0=Open] *)

    (* --- Kinematic Kinematics & Position Sensors --- *)
    rTrolleyVel_mps         : REAL;     (* Dual-Wheel Optical Incremental Encoder Ground Speed [m/s], Range [-6.0..+6.0] *)
    rTrolleyPos_m           : REAL;     (* Absolute Laser Barcode / Linear Transducer Girder Coordinate [m], Range [0.0..185.0] *)
    rTargetPos_m            : REAL;     (* Supervisory Terminal Operating System (TOS) Target Coordinate Command [m] *)

    (* --- 2oo3 Triple Modular Redundant (TMR) Optical Laser Rangefinders --- *)
    rLaserDist_ChA_m        : REAL;     (* Primary Optical ToF Laser Distance Sensor Channel A [m], Range [0.0..200.0] *)
    rLaserDist_ChB_m        : REAL;     (* Secondary Optical ToF Laser Distance Sensor Channel B [m], Range [0.0..200.0] *)
    rLaserDist_ChC_m        : REAL;     (* Tertiary Optical Phase-Shift Distance Sensor Channel C [m], Range [0.0..200.0] *)
    bLaserSignalOk_ChA      : BOOL;     (* Optical Signal Quality & Internal Self-Diagnostic Flag Channel A [1=Valid, 0=Fault] *)
    bLaserSignalOk_ChB      : BOOL;     (* Optical Signal Quality & Internal Self-Diagnostic Flag Channel B [1=Valid, 0=Fault] *)
    bLaserSignalOk_ChC      : BOOL;     (* Optical Signal Quality & Internal Self-Diagnostic Flag Channel C [1=Valid, 0=Fault] *)

    (* --- Power Electronics & Regenerative Bus Transducers --- *)
    rVdcBus_V               : REAL;     (* Common DC Intermediate Bus Voltage Transducer [V], Nominal 690V AC / 930V DC Peak *)
    rChopperCurrent_A       : REAL;     (* Braking Resistor Current Transducer (Hall Effect) [A], Range [0.0..1200.0] *)
    rResistorTemp_degC      : REAL;     (* Braking Resistor Bank Embedded Mineral-Insulated PT100 RTD Core Temp [deg C] *)
    rAmbientTemp_degC       : REAL;     (* Girder Electrical Enclosure Ambient Temperature Transducer [deg C] *)

    (* --- Execution Parameters --- *)
    rCycleTime_s            : REAL;     (* Deterministic PLC Execution Task Period [s], Calibrated at 0.005 (5 ms) *)
END_VAR

VAR_OUTPUT
    (* --- Inverter & Motion Commands --- *)
    bTrolleyPermissive      : BOOL;     (* Motion Interlock Output to VFD Drive Inverter [1=Motion Permitted, 0=Inhibited] *)
    rVelocitySetpoint_mps   : REAL;     (* Dynamically Shaped S-Curve Trajectory Velocity Command [m/s] *)
    rDriveTorqueLimit_pct   : REAL;     (* Adaptive Symmetrical Drive Motoring/Regenerative Torque Limit [%, 0.0..100.0] *)
    bMechanicalBrakeCommand : BOOL;     (* Electro-Hydraulic Track Clamp Release Command [1=Release/Lift, 0=Apply Spring Clamp] *)

    (* --- Power Electronics Modulation --- *)
    rChopperDuty_pct        : REAL;     (* Dynamic Braking IGBT Resistor Chopper Gate PWM Duty Ratio [%, 0.0..100.0] *)
    bChopperFired           : BOOL;     (* Direct High-Speed Gate Driver Trigger Active Status Flag *)

    (* --- Thermal & Kinematic Diagnostics --- *)
    rSafeBrakingDistance_m  : REAL;     (* Continuous Real-Time Computed Emergency Stopping Distance Envelope [m] *)
    rResistorThermalStress_pct : REAL;  (* Lumped-Parameter Resistor Bank Thermal Accumulator [% of Ultimate Capacity] *)
    rVotedDistance_m        : REAL;     (* High-Integrity 2oo3 TMR Fused Distance to Forward Boom/Obstacle Obstruction [m] *)
    bCollisionWarning       : BOOL;     (* Proximity Intrusion Warning: Trolley Within Emergency Deceleration Corridor *)
    bDegradedSpeedMode      : BOOL;     (* Sensor Channel Divergence or Thermal Derating Active Speed Clamping Mode *)

    (* --- Status & Comprehensive Diagnostic Words --- *)
    wStatusWord             : WORD;     (* Bit-Mapped Operational State & Health Status:
                                           Bit 00: Operational Permissive Active
                                           Bit 01: Trajectory Active
                                           Bit 02: Dynamic Braking Active
                                           Bit 03: Mechanical Brake Released
                                           Bit 04: 2oo3 Full Redundancy Healthy
                                           Bit 05: 1oo2 Degraded Redundancy Active
                                           Bit 06: Degraded Creep Speed Clamped
                                           Bit 07: Thermal Derate Engaged
                                           Bit 08..15: State Machine State Code *)
    wFaultCode              : WORD;     (* Bit-Mapped Safety Trip Alarms:
                                           Bit 00: E-Stop Circuit Open / Tripped
                                           Bit 01: Critical DC Bus Overvoltage (>860V)
                                           Bit 02: Resistor Bank Thermal Overload (>450C)
                                           Bit 03: All 3 Laser Sensors Divergent / Failed
                                           Bit 04: Emergency Safe Stopping Envelope Breach
                                           Bit 05: Mechanical Brake Feedback Contactor Discrepancy
                                           Bit 06: Velocity Slip / Wheel-Rail Adhesion Loss
                                           Bit 07: Chopper Shoot-Through / Transducer Fault *)
END_VAR

VAR
    (* --- State Machine Registers --- *)
    iState                  : INT := 0; (* 0=INIT, 10=STANDBY, 20=MPC_TRAJECTORY, 30=CONTROLLED_DECEL, 40=DYNAMIC_ESTOP, 50=THERMAL_LOCKOUT, 99=FATAL_FAULT *)
    iPreviousState          : INT := 0;
    rStateTimer_s           : REAL := 0.0;

    (* --- 2oo3 Triple Modular Redundancy (TMR) Engine --- *)
    bChA_Valid              : BOOL;
    bChB_Valid              : BOOL;
    bChC_Valid              : BOOL;
    iValidLaserCount        : INT;
    rDiffAB_m               : REAL;
    rDiffBC_m               : REAL;
    rDiffCA_m               : REAL;
    rLaserMedian_m          : REAL;
    rTMRDiscrepancyTol_m    : REAL := 0.28; (* Allowed Disparity Tolerance Between Calibrated Beams [m] *)
    rLaserMinValidDist_m    : REAL := 0.15; (* Minimum Optical Blind-Zone Threshold [m] *)
    rLaserMaxValidDist_m    : REAL := 195.0;(* Maximum Valid Girder Track Runway Distance [m] *)

    (* --- Dynamic Braking Chopper Hysteresis & Thermal Observer --- *)
    rVdcChopperTurnOn_V     : REAL := 725.0; (* DC Bus Upper Switch-On Threshold for IGBT PWM Chopping [V] *)
    rVdcChopperTurnOff_V    : REAL := 695.0; (* DC Bus Lower Switch-Off Hysteresis Extinction Limit [V] *)
    rVdcChopperFullDuty_V   : REAL := 820.0; (* DC Bus Full 100% Saturation Voltage [V] *)
    rVdcCriticalTrip_V      : REAL := 875.0; (* Inverter Destruction Immediate Crowbar / Trip Voltage [V] *)

    (* First-Order Lumped Thermal Observer Parameters: dE/dt = Pin - (UA)*(T_core - T_amb) *)
    rResistorResistance_Ohm : REAL := 2.85;     (* Resistor Grid Effective High-Power Resistance [Ohms] *)
    rThermalMass_JpK        : REAL := 210000.0; (* Resistor Thermal Mass (Stainless Steel Grid) [J / deg K] *)
    rHeatDissipation_WpK    : REAL := 285.0;    (* Convective Heat Dissipation Constant U*A [W / deg K] *)
    rObserverCoreTemp_degC  : REAL := 30.0;     (* Continuous Mathematical State Variable for Core Temp [deg C] *)
    rMaxOperatingTemp_degC  : REAL := 450.0;    (* Resistor Thermal Rating Cut-Off Limit [deg C] *)
    rWarningOperatingTemp_degC : REAL := 370.0; (* Thermal Derating Speed Limitation Threshold [deg C] *)
    rResistorMaxJoules_J    : REAL := 95000000.0; (* Total Cumulative Energy Absorbing Capacity [Joules] *)
    rCurrentEnergyStored_J  : REAL := 0.0;
    rInstantPower_W         : REAL := 0.0;

    (* --- Model Predictive Kinematics, State-Space Observer & Collision Envelope --- *)
    (* State Vector: x = [Position, Velocity, Acceleration]^T *)
    rObsPos_m               : REAL := 0.0;
    rObsVel_mps             : REAL := 0.0;
    rObsAcc_mps2            : REAL := 0.0;

    (* Discrete State Space Observer Matrices (Ts = rCycleTime_s = 0.005s) *)
    (* x(k+1) = Ad * x(k) + Bd * u(k) + L * (y(k) - C * x(k))              *)
    rL_PosGain              : REAL := 0.185; (* Kalman/Luenberger Position Observer Innovation Gain *)
    rL_VelGain              : REAL := 0.320; (* Kalman/Luenberger Velocity Observer Innovation Gain *)

    (* Mechanical Physical Kinematic Boundaries *)
    rMaxServiceVel_mps      : REAL := 4.20;  (* Maximum Service Rail Velocity [m/s] *)
    rCreepSpeed_mps         : REAL := 0.75;  (* Degraded / Final Approach Creep Speed [m/s] *)
    rMaxServiceAcc_mps2     : REAL := 0.75;  (* Maximum Permissible Acceleration Rate [m/s^2] *)
    rMaxServiceDecel_mps2   : REAL := 0.85;  (* Maximum Permissible Normal Deceleration Rate [m/s^2] *)
    rEmergencyDecel_mps2    : REAL := 1.75;  (* Full Mechanical + Dynamic Electric Deceleration [m/s^2] *)
    rMaxServiceJerk_mps3    : REAL := 1.25;  (* Anti-Sway Jerk Limitation Rate [m/s^3] *)
    rOpticalSafetyMargin_m  : REAL := 4.00;  (* Absolute Hard Buffer Separation Distance [m] *)
    rSystemReactionTime_s   : REAL := 0.140; (* Combined PLC Cycle + Inverter Torque Loop Delay [s] *)

    (* Trajectory Profiler Internal Variables *)
    rPositionError_m        : REAL := 0.0;
    rDecelDistanceTarget_m  : REAL := 0.0;
    rTargetVelocity_mps     : REAL := 0.0;
    rMaxSpeedPermitted_mps  : REAL := 4.20;
    rFilteredVelocityCmd_mps: REAL := 0.0;

    (* --- Slip / Slide Detection --- *)
    rOpticalDerivedVel_mps  : REAL := 0.0;
    rPrevVotedDistance_m    : REAL := 0.0;
    rSlipDiscrepancy_mps    : REAL := 0.0;
    rSlipAlarmDebounce_s    : REAL := 0.0;

    (* --- Fault Matrix Latches --- *)
    wFaultLatch             : WORD := 16#0000;
END_VAR

(*
====================================================================================================
 1. PRE-EXECUTION DIAGNOSTICS & SAFETY INTEGRITY VERIFICATION
====================================================================================================
*)
(* Verify Hardwired E-Stop Circuit *)
IF NOT bEStopOk THEN
    wFaultLatch := wFaultLatch OR 16#0001; (* Bit 0: E-Stop Activated *)
END_IF;

(* Inverter Intermediate DC Bus Overvoltage Surveillance *)
IF rVdcBus_V >= rVdcCriticalTrip_V THEN
    wFaultLatch := wFaultLatch OR 16#0002; (* Bit 1: Destructive DC Bus Overvoltage *)
END_IF;

(* Mechanical Friction Brake Command vs Auxiliary Contactor Feedback Verification *)
IF (bMechanicalBrakeCommand AND NOT bBrakeContactorsClosed) OR 
   (NOT bMechanicalBrakeCommand AND bBrakeContactorsClosed AND (rStateTimer_s > 0.8)) THEN
    wFaultLatch := wFaultLatch OR 16#0020; (* Bit 5: Friction Brake Contactor Discrepancy *)
END_IF;

(*
====================================================================================================
 2. 2oo3 TRIPLE MODULAR REDUNDANCY (TMR) OPTICAL LASER VOTING ENGINE
====================================================================================================
*)
(* Channel Validity Assessment: Check optical status flag and operational range validity *)
bChA_Valid := bLaserSignalOk_ChA AND (rLaserDist_ChA_m >= rLaserMinValidDist_m) AND (rLaserDist_ChA_m <= rLaserMaxValidDist_m);
bChB_Valid := bLaserSignalOk_ChB AND (rLaserDist_ChB_m >= rLaserMinValidDist_m) AND (rLaserDist_ChB_m <= rLaserMaxValidDist_m);
bChC_Valid := bLaserSignalOk_ChC AND (rLaserDist_ChC_m >= rLaserMinValidDist_m) AND (rLaserDist_ChC_m <= rLaserMaxValidDist_m);

(* Summation of Healthy Channels *)
iValidLaserCount := 0;
IF bChA_Valid THEN iValidLaserCount := iValidLaserCount + 1; END_IF;
IF bChB_Valid THEN iValidLaserCount := iValidLaserCount + 1; END_IF;
IF bChC_Valid THEN iValidLaserCount := iValidLaserCount + 1; END_IF;

(* Calculate Cross-Channel Absolute Disparities *)
rDiffAB_m := ABS(rLaserDist_ChA_m - rLaserDist_ChB_m);
rDiffBC_m := ABS(rLaserDist_ChB_m - rLaserDist_ChC_m);
rDiffCA_m := ABS(rLaserDist_ChC_m - rLaserDist_ChA_m);

(* Execution of 2oo3 Voting & Fault Isolation Logic *)
IF iValidLaserCount = 3 THEN
    (* Full Triple Modular Redundancy Available: Compute Exact Median *)
    IF (rLaserDist_ChA_m <= rLaserDist_ChB_m AND rLaserDist_ChB_m <= rLaserDist_ChC_m) OR
       (rLaserDist_ChC_m <= rLaserDist_ChB_m AND rLaserDist_ChB_m <= rLaserDist_ChA_m) THEN
        rLaserMedian_m := rLaserDist_ChB_m;
    ELSIF (rLaserDist_ChB_m <= rLaserDist_ChA_m AND rLaserDist_ChA_m <= rLaserDist_ChC_m) OR
          (rLaserDist_ChC_m <= rLaserDist_ChA_m AND rLaserDist_ChA_m <= rLaserDist_ChB_m) THEN
        rLaserMedian_m := rLaserDist_ChA_m;
    ELSE
        rLaserMedian_m := rLaserDist_ChC_m;
    END_IF;

    (* Check for Individual Beam Drift from Median *)
    IF (ABS(rLaserDist_ChA_m - rLaserMedian_m) > rTMRDiscrepancyTol_m) OR
       (ABS(rLaserDist_ChB_m - rLaserMedian_m) > rTMRDiscrepancyTol_m) OR
       (ABS(rLaserDist_ChC_m - rLaserMedian_m) > rTMRDiscrepancyTol_m) THEN
        (* Single sensor divergence detected; isolate and flag degraded tracking *)
        bDegradedSpeedMode := TRUE;
    ELSE
        bDegradedSpeedMode := FALSE;
    END_IF;
    rVotedDistance_m := rLaserMedian_m;

ELSIF iValidLaserCount = 2 THEN
    (* Graceful Degradation: 1oo2 Dual Redundancy Mode *)
    bDegradedSpeedMode := TRUE;
    IF bChA_Valid AND bChB_Valid THEN
        IF rDiffAB_m <= rTMRDiscrepancyTol_m THEN
            rVotedDistance_m := (rLaserDist_ChA_m + rLaserDist_ChB_m) * 0.5;
        ELSE
            (* Incongruent pair: select conservative minimum distance to guarantee safety *)
            IF rLaserDist_ChA_m < rLaserDist_ChB_m THEN
                rVotedDistance_m := rLaserDist_ChA_m;
            ELSE
                rVotedDistance_m := rLaserDist_ChB_m;
            END_IF;
        END_IF;
    ELSIF bChB_Valid AND bChC_Valid THEN
        IF rDiffBC_m <= rTMRDiscrepancyTol_m THEN
            rVotedDistance_m := (rLaserDist_ChB_m + rLaserDist_ChC_m) * 0.5;
        ELSE
            IF rLaserDist_ChB_m < rLaserDist_ChC_m THEN
                rVotedDistance_m := rLaserDist_ChB_m;
            ELSE
                rVotedDistance_m := rLaserDist_ChC_m;
            END_IF;
        END_IF;
    ELSE (* bChA_Valid AND bChC_Valid *)
        IF rDiffCA_m <= rTMRDiscrepancyTol_m THEN
            rVotedDistance_m := (rLaserDist_ChA_m + rLaserDist_ChC_m) * 0.5;
        ELSE
            IF rLaserDist_ChA_m < rLaserDist_ChC_m THEN
                rVotedDistance_m := rLaserDist_ChA_m;
            ELSE
                rVotedDistance_m := rLaserDist_ChC_m;
            END_IF;
        END_IF;
    END_IF;

ELSIF iValidLaserCount = 1 THEN
    (* Severe Degradation: 1oo1 Single Sensor Survival Mode *)
    bDegradedSpeedMode := TRUE;
    IF bChA_Valid THEN
        rVotedDistance_m := rLaserDist_ChA_m;
    ELSIF bChB_Valid THEN
        rVotedDistance_m := rLaserDist_ChB_m;
    ELSE
        rVotedDistance_m := rLaserDist_ChC_m;
    END_IF;

ELSE
    (* Total Sensor Blindness: All 3 Channels Invalid *)
    wFaultLatch := wFaultLatch OR 16#0008; (* Bit 3: All 3 Lasers Failed *)
    rVotedDistance_m := 0.0;
    bDegradedSpeedMode := TRUE;
END_IF;

(* Laser Derivative Velocity Calculation & Wheel-Rail Slip Monitor *)
IF rCycleTime_s > 0.001 AND rPrevVotedDistance_m > 0.1 AND rVotedDistance_m > 0.1 THEN
    rOpticalDerivedVel_mps := -(rVotedDistance_m - rPrevVotedDistance_m) / rCycleTime_s;
    rSlipDiscrepancy_mps := ABS(rTrolleyVel_mps - rOpticalDerivedVel_mps);

    (* If wheel speed diverges from optical speed by > 0.85 m/s for > 150ms, trip slip alarm *)
    IF rSlipDiscrepancy_mps > 0.85 THEN
        rSlipAlarmDebounce_s := rSlipAlarmDebounce_s + rCycleTime_s;
        IF rSlipAlarmDebounce_s > 0.150 THEN
            wFaultLatch := wFaultLatch OR 16#0040; (* Bit 6: Severe Wheel Slip / Slide *)
        END_IF;
    ELSE
        rSlipAlarmDebounce_s := 0.0;
    END_IF;
END_IF;
rPrevVotedDistance_m := rVotedDistance_m;

(*
====================================================================================================
 3. DYNAMIC BRAKING RESISTOR CHOPPER MODULATION & THERMAL OBSERVER
====================================================================================================
*)
(* Instantaneous Regenerative Chopper Power Calculation: P = V_dc * I_chopper *)
rInstantPower_W := rVdcBus_V * rChopperCurrent_A;

(* High-Speed Chopper IGBT Duty Ratio Modulation with Hysteresis *)
IF rVdcBus_V >= rVdcChopperTurnOn_V THEN
    bChopperFired := TRUE;
    (* Proportional Modulation between Turn-On Voltage (725V) and Saturated Limit (820V) *)
    rChopperDuty_pct := ((rVdcBus_V - rVdcChopperTurnOff_V) / (rVdcChopperFullDuty_V - rVdcChopperTurnOff_V)) * 100.0;
    IF rChopperDuty_pct > 100.0 THEN
        rChopperDuty_pct := 100.0;
    ELSIF rChopperDuty_pct < 5.0 THEN
        rChopperDuty_pct := 5.0;
    END_IF;
ELSIF rVdcBus_V <= rVdcChopperTurnOff_V THEN
    bChopperFired := FALSE;
    rChopperDuty_pct := 0.0;
ELSE
    (* Inside Hysteresis Deadband [695V .. 725V]: Retain Active State If Already Chopping *)
    IF bChopperFired THEN
        rChopperDuty_pct := ((rVdcBus_V - rVdcChopperTurnOff_V) / (rVdcChopperFullDuty_V - rVdcChopperTurnOff_V)) * 100.0;
    ELSE
        rChopperDuty_pct := 0.0;
    END_IF;
END_IF;

(* Shoot-Through Diagnostic: Current flowing when Chopper is NOT fired *)
IF (NOT bChopperFired) AND (rChopperCurrent_A > 45.0) THEN
    wFaultLatch := wFaultLatch OR 16#0080; (* Bit 7: Chopper Transistor Leakage / Shoot-Through *)
END_IF;

(* First-Order Lumped Differential Thermal Observer *)
(* d(T_core)/dt = (P_in - U*A*(T_core - T_amb)) / C_th *)
IF rThermalMass_JpK > 1000.0 AND rCycleTime_s > 0.0001 THEN
    rObserverCoreTemp_degC := rObserverCoreTemp_degC + 
        ((rInstantPower_W - (rHeatDissipation_WpK * (rObserverCoreTemp_degC - rAmbientTemp_degC))) / rThermalMass_JpK) * rCycleTime_s;
END_IF;

(* Fusion with Physical Embedded RTD Sensor to Guard Against Parameter Drift *)
IF rResistorTemp_degC > rObserverCoreTemp_degC THEN
    rObserverCoreTemp_degC := (0.97 * rObserverCoreTemp_degC) + (0.03 * rResistorTemp_degC);
END_IF;

(* Thermal Energy Accumulation Index [% of Ultimate Capability] *)
rResistorThermalStress_pct := ((rObserverCoreTemp_degC - rAmbientTemp_degC) / (rMaxOperatingTemp_degC - rAmbientTemp_degC)) * 100.0;
IF rResistorThermalStress_pct < 0.0 THEN
    rResistorThermalStress_pct := 0.0;
ELSIF rResistorThermalStress_pct > 150.0 THEN
    rResistorThermalStress_pct := 150.0;
END_IF;

(* Thermal Stress Supervisory Protection *)
IF rObserverCoreTemp_degC >= rMaxOperatingTemp_degC THEN
    wFaultLatch := wFaultLatch OR 16#0004; (* Bit 2: Critical Resistor Grid Overheating *)
ELSIF rObserverCoreTemp_degC >= rWarningOperatingTemp_degC THEN
    bDegradedSpeedMode := TRUE; (* Impose thermal speed reduction *)
END_IF;

(*
====================================================================================================
 4. MODEL PREDICTIVE KINEMATIC ANTI-COLLISION & TRAJECTORY GENERATION
====================================================================================================
*)
(* Continuous Calculation of Safe Stopping Distance Envelope:
   d_stop = v*t_rxn + v^2 / (2 * a_decel) + (v * a_decel) / (2 * jerk_max) + d_buffer *)
rSafeBrakingDistance_m := (ABS(rTrolleyVel_mps) * rSystemReactionTime_s) + 
                          ((rTrolleyVel_mps * rTrolleyVel_mps) / (2.0 * rEmergencyDecel_mps2)) + 
                          ((ABS(rTrolleyVel_mps) * rEmergencyDecel_mps2) / (2.0 * rMaxServiceJerk_mps3)) + 
                          rOpticalSafetyMargin_m;

(* Collision Boundary Proximity Assessment *)
IF (rVotedDistance_m <= rSafeBrakingDistance_m) AND (rVotedDistance_m > 0.05) THEN
    bCollisionWarning := TRUE;
    IF rVotedDistance_m <= (rSafeBrakingDistance_m * 0.75) THEN
        wFaultLatch := wFaultLatch OR 16#0010; (* Bit 4: Emergency Safe Corridor Violation *)
    END_IF;
ELSE
    bCollisionWarning := FALSE;
END_IF;

(* Luenberger / State-Space Kinematic Estimator Update *)
(* x_pos(k+1) = x_pos(k) + Ts * x_vel(k) + L_pos * (y_pos - x_pos) *)
rObsPos_m := rObsPos_m + (rCycleTime_s * rObsVel_mps) + (rL_PosGain * (rTrolleyPos_m - rObsPos_m));
rObsVel_mps := rObsVel_mps + (rCycleTime_s * rObsAcc_mps2) + (rL_VelGain * (rTrolleyVel_mps - rObsVel_mps));
rObsAcc_mps2 := (rTrolleyVel_mps - rObsVel_mps) / (rCycleTime_s + 0.001);

(* Dynamic Trajectory Shaping & Target Speed Calculation *)
rPositionError_m := rTargetPos_m - rTrolleyPos_m;

(* Determine Slew-Rate Permitted Velocity Command Based on Target Distance *)
IF ABS(rPositionError_m) > 0.05 THEN
    rDecelDistanceTarget_m := (rTrolleyVel_mps * rTrolleyVel_mps) / (2.0 * rMaxServiceDecel_mps2);
    IF ABS(rPositionError_m) > rDecelDistanceTarget_m THEN
        IF rPositionError_m > 0.0 THEN
            rTargetVelocity_mps := rMaxServiceVel_mps;
        ELSE
            rTargetVelocity_mps := -rMaxServiceVel_mps;
        END_IF;
    ELSE
        (* Square-Root Deceleration Trajectory Profile *)
        IF rPositionError_m > 0.0 THEN
            rTargetVelocity_mps := SQRT(2.0 * rMaxServiceDecel_mps2 * ABS(rPositionError_m));
        ELSE
            rTargetVelocity_mps := -SQRT(2.0 * rMaxServiceDecel_mps2 * ABS(rPositionError_m));
        END_IF;
    END_IF;
ELSE
    rTargetVelocity_mps := 0.0;
END_IF;

(* Anti-Collision Optical Override: Restrict Forward Velocity if Approaching Obstacle *)
IF (rVotedDistance_m > 0.1) AND (rTargetVelocity_mps > 0.0) THEN
    IF rVotedDistance_m < (rSafeBrakingDistance_m + 8.0) THEN
        rMaxSpeedPermitted_mps := SQRT(MAX(0.0, 2.0 * rMaxServiceDecel_mps2 * (rVotedDistance_m - rOpticalSafetyMargin_m)));
        IF rTargetVelocity_mps > rMaxSpeedPermitted_mps THEN
            rTargetVelocity_mps := rMaxSpeedPermitted_mps;
        END_IF;
    END_IF;
END_IF;

(* Degraded Speed Enforcement *)
IF bDegradedSpeedMode THEN
    IF rTargetVelocity_mps > rCreepSpeed_mps THEN
        rTargetVelocity_mps := rCreepSpeed_mps;
    ELSIF rTargetVelocity_mps < -rCreepSpeed_mps THEN
        rTargetVelocity_mps := -rCreepSpeed_mps;
    END_IF;
END_IF;

(*
====================================================================================================
 5. DETERMINISTIC FINITE STATE MACHINE (FSM)
====================================================================================================
*)
(* Update State Timer *)
IF iState = iPreviousState THEN
    rStateTimer_s := rStateTimer_s + rCycleTime_s;
ELSE
    rStateTimer_s := 0.0;
    iPreviousState := iState;
END_IF;

(* Unconditional Transition to Lockout or E-Stop on Active Faults *)
IF (wFaultLatch <> 16#0000) AND (iState <> 40) AND (iState <> 50) AND (iState <> 99) THEN
    IF (wFaultLatch AND 16#0004) <> 16#0000 THEN
        iState := 50; (* Transition to Resistor Cooling Lockout *)
    ELSIF (wFaultLatch AND 16#0001) <> 16#0000 OR (wFaultLatch AND 16#0010) <> 16#0000 THEN
        iState := 40; (* Transition to Dynamic Emergency Stop *)
    ELSE
        iState := 99; (* Transition to General Fault Lockout *)
    END_IF;
END_IF;

CASE iState OF
    0: (* STATE 0: INITIALIZATION & HARDWARE SELF-TEST *)
        bTrolleyPermissive := FALSE;
        bMechanicalBrakeCommand := FALSE; (* Clamp Brakes *)
        rVelocitySetpoint_mps := 0.0;
        rDriveTorqueLimit_pct := 0.0;
        rFilteredVelocityCmd_mps := 0.0;

        (* Self-Test Criteria: All sensors responsive, DC Bus healthy, safety chain closed *)
        IF bEStopOk AND (wFaultLatch = 16#0000) AND (iValidLaserCount >= 2) AND 
           (rVdcBus_V > 580.0) AND (rVdcBus_V < 750.0) THEN
            IF bEnable THEN
                iState := 10; (* Progress to Standby *)
            END_IF;
        END_IF;

    10: (* STATE 10: STANDBY & ZERO-SPEED HOLD *)
        bTrolleyPermissive := TRUE;
        bMechanicalBrakeCommand := FALSE; (* Hold Mechanical Track Clamps until Motion Commanded *)
        rVelocitySetpoint_mps := 0.0;
        rDriveTorqueLimit_pct := 25.0;    (* Hold-Torque Zero Speed Bias *)
        rFilteredVelocityCmd_mps := 0.0;

        IF NOT bEnable THEN
            iState := 0;
        ELSIF ABS(rTargetPos_m - rTrolleyPos_m) > 0.08 THEN
            bMechanicalBrakeCommand := TRUE; (* Release Mechanical Brakes *)
            IF bBrakeContactorsClosed AND (rStateTimer_s > 0.25) THEN
                iState := 20; (* Launch Trajectory Tracking *)
            END_IF;
        END_IF;

    20: (* STATE 20: ACTIVE MPC TRAJECTORY FOLLOWING *)
        bTrolleyPermissive := TRUE;
        bMechanicalBrakeCommand := TRUE; (* Brakes Released *)

        (* Adaptive Torque Limiting based on Thermal Reserve *)
        IF bDegradedSpeedMode THEN
            rDriveTorqueLimit_pct := 65.0;
        ELSE
            rDriveTorqueLimit_pct := 100.0;
        END_IF;

        (* Slew-Rate Rate-Limiter (Jerk and Acceleration Constrained Velocity Profiler) *)
        IF rFilteredVelocityCmd_mps < rTargetVelocity_mps THEN
            rFilteredVelocityCmd_mps := rFilteredVelocityCmd_mps + (rMaxServiceAcc_mps2 * rCycleTime_s);
            IF rFilteredVelocityCmd_mps > rTargetVelocity_mps THEN
                rFilteredVelocityCmd_mps := rTargetVelocity_mps;
            END_IF;
        ELSIF rFilteredVelocityCmd_mps > rTargetVelocity_mps THEN
            rFilteredVelocityCmd_mps := rFilteredVelocityCmd_mps - (rMaxServiceDecel_mps2 * rCycleTime_s);
            IF rFilteredVelocityCmd_mps < rTargetVelocity_mps THEN
                rFilteredVelocityCmd_mps := rTargetVelocity_mps;
            END_IF;
        END_IF;
        rVelocitySetpoint_mps := rFilteredVelocityCmd_mps;

        (* Transition to Controlled Deceleration when entering proximity or destination deadband *)
        IF ABS(rPositionError_m) <= 0.60 OR bCollisionWarning THEN
            iState := 30;
        END_IF;

    30: (* STATE 30: CONTROLLED TERMINAL DECELERATION & TARGET LOCK *)
        bTrolleyPermissive := TRUE;
        bMechanicalBrakeCommand := TRUE;
        rDriveTorqueLimit_pct := 85.0;

        (* Aggressive Deceleration Ramp *)
        IF rFilteredVelocityCmd_mps > 0.0 THEN
            rFilteredVelocityCmd_mps := rFilteredVelocityCmd_mps - (rMaxServiceDecel_mps2 * 1.25 * rCycleTime_s);
            IF rFilteredVelocityCmd_mps < 0.0 THEN rFilteredVelocityCmd_mps := 0.0; END_IF;
        ELSIF rFilteredVelocityCmd_mps < 0.0 THEN
            rFilteredVelocityCmd_mps := rFilteredVelocityCmd_mps + (rMaxServiceDecel_mps2 * 1.25 * rCycleTime_s);
            IF rFilteredVelocityCmd_mps > 0.0 THEN rFilteredVelocityCmd_mps := 0.0; END_IF;
        END_IF;
        rVelocitySetpoint_mps := rFilteredVelocityCmd_mps;

        (* Zero-Speed Docking Condition Reached *)
        IF (ABS(rTrolleyVel_mps) < 0.04) AND (rStateTimer_s > 0.40) THEN
            iState := 10; (* Return to Standby *)
        END_IF;

    40: (* STATE 40: DYNAMIC EMERGENCY BRAKING & REGENERATIVE CLAMP *)
        bTrolleyPermissive := FALSE; (* Inhibit Motoring *)
        rVelocitySetpoint_mps := 0.0;
        rDriveTorqueLimit_pct := 100.0; (* Full Regenerative Electric Braking Torque Available *)

        (* Rapid Controlled Electrical Deceleration, Followed by Spring Brake Drop *)
        IF ABS(rTrolleyVel_mps) > 0.35 THEN
            bMechanicalBrakeCommand := TRUE; (* Rely on Inverter + Chopper to Absorb Kinetic Energy *)
        ELSE
            bMechanicalBrakeCommand := FALSE; (* Drop Friction Clamps below 0.35 m/s to prevent rail burn *)
        END_IF;

        (* Stay locked in Emergency State until fully stopped, E-Stop reset, and Enable toggled *)
        IF (ABS(rTrolleyVel_mps) < 0.02) AND bEStopOk AND NOT bEnable THEN
            wFaultLatch := wFaultLatch AND NOT 16#0001; (* Clear E-Stop latch on operator cycle *)
            wFaultLatch := wFaultLatch AND NOT 16#0010;
            iState := 0;
        END_IF;

    50: (* STATE 50: RESISTOR CORE THERMAL OVERLOAD COOLING LOCKOUT *)
        bTrolleyPermissive := FALSE;
        bMechanicalBrakeCommand := FALSE; (* Lock Mechanical Brakes *)
        rVelocitySetpoint_mps := 0.0;
        rDriveTorqueLimit_pct := 0.0;

        (* Await Natural / Forced Convective Resistor Cooling down to safe restart threshold (110 deg C) *)
        IF (rObserverCoreTemp_degC < 110.0) AND (rResistorTemp_degC < 110.0) THEN
            wFaultLatch := wFaultLatch AND NOT 16#0004; (* Clear Thermal Fault *)
            iState := 0;
        END_IF;

    99: (* STATE 99: CRITICAL HARDWARE FAULT LOCKOUT *)
        bTrolleyPermissive := FALSE;
        bMechanicalBrakeCommand := FALSE; (* Instant Clamping *)
        rVelocitySetpoint_mps := 0.0;
        rDriveTorqueLimit_pct := 0.0;

        (* Manual Reset Sequence Required: Drop Enable, Await Fault Clearance *)
        IF NOT bEnable AND (wFaultLatch = 16#0000) THEN
            iState := 0;
        END_IF;

END_CASE;

(*
====================================================================================================
 6. STATUS WORD & FAULT PACKING
====================================================================================================
*)
wFaultCode := wFaultLatch;

(* Pack Subsystem Status Register *)
wStatusWord := 16#0000;
IF bTrolleyPermissive THEN wStatusWord := wStatusWord OR 16#0001; END_IF;
IF (iState = 20) OR (iState = 30) THEN wStatusWord := wStatusWord OR 16#0002; END_IF;
IF bChopperFired THEN wStatusWord := wStatusWord OR 16#0004; END_IF;
IF bBrakeContactorsClosed THEN wStatusWord := wStatusWord OR 16#0008; END_IF;
IF iValidLaserCount = 3 THEN wStatusWord := wStatusWord OR 16#0010; END_IF;
IF iValidLaserCount = 2 THEN wStatusWord := wStatusWord OR 16#0020; END_IF;
IF bDegradedSpeedMode THEN wStatusWord := wStatusWord OR 16#0040; END_IF;
IF rObserverCoreTemp_degC >= rWarningOperatingTemp_degC THEN wStatusWord := wStatusWord OR 16#0080; END_IF;

(* Encode Finite State Machine ID into High Byte of Status Word *)
wStatusWord := wStatusWord OR SHL(INT_TO_WORD(iState), 8);

END_FUNCTION_BLOCK
